import sys

# sys._is_gil_enabled() only exists on Python 3.13+; older interpreters
# always have the GIL, so provide a fallback that reports True.
if not hasattr(sys, "_is_gil_enabled"):
    sys._is_gil_enabled = lambda: True

if sys._is_gil_enabled():
    print("GIL enabled")
else:
    print("GIL disabled")
